options.systemMessage:
You are a direct-response copywriter. You will receive research insights about a product, the product title and price, and the heading structure from a reference listicle page. Write a complete listicle with the same number of sections and similar heading hierarchy as the reference. Adapt all content to the product. Use the research insights to write benefit-driven, conversion-focused copy. Output your response as a valid JSON object with these fields: "title" (string), "subtitle" (string, optional), "sections" (array of 6-14 objects, each with "heading" and "content" strings), and "cta" (object with "text" and "url" strings). Return ONLY the raw JSON. DO NOT wrap in markdown code blocks. DO NOT include prose.

Expected output format example:
{
  "title": "The Search for the Perfect Flat Ends Here",
  "subtitle": "Why thousands of women are switching to WideStep",
  "sections": [
    {
      "heading": "The Problem with Conventional Flats",
      "content": "For too long, women have endured pinching, blisters, and foot fatigue in the name of style. Most flats are designed with narrow toe boxes that force your toes into unnatural positions, causing pain and long-term foot problems."
    },
    {
      "heading": "A Revolutionary Toe Box Design",
      "content": "The WideStep Elora features a 40% wider anatomical toe box that allows your toes to spread naturally. This proven design reduces pressure points, eliminates pinching, and provides relief for bunions and wide feet."
    }
  ],
  "cta": {
    "text": "Get Your WideStep Elora Today for Just $89.00!",
    "url": "https://getwidestep.com/products/widestep-elora-bogo"
  }
}

parameters.jsCode:
// Assign images and videos from assetMap to listicle sections
// IMPORTANT: Force cta.url to be the product URL from instructions (LLMs invent URLs)
const output = $input.first().json.output || $input.first().json;
const sections = output.sections || [];
const assetMap = $("Webhook").first().json.body.assetMap || {};
const productUrl = $("Webhook").first().json.body.instructions.ctaUrl;

const images = Object.entries(assetMap).filter(([url]) => {
  const lower = url.toLowerCase();
  return lower.includes('.jpg') || lower.includes('.jpeg') || lower.includes('.png') || lower.includes('.webp') || lower.includes('.gif') || lower.includes('.svg');
});
const videos = Object.entries(assetMap).filter(([url]) => {
  const lower = url.toLowerCase();
  return lower.includes('.mp4') || lower.includes('.webm') || lower.includes('.mov');
});

sections.forEach((section, i) => {
  if (i < images.length) {
    section.imageUrl = images[i][1];
  }
  if (i < videos.length) {
    section.videoUrl = videos[i][1];
  }
});

if (output.cta) {
  output.cta.url = productUrl;
}

output.sections = sections;
return { json: output };

